def run_length_encode(s):
    if s == '':
        return ''

    result = []
    count = 1
    prev = s[0]

    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1

    result.append(prev + str(count))  # append the last run
    return ''.join(result)
```

